    else
        self.polling = nil
        frame:SetScript("OnUpdate", nil)
        elapsed = 0
    end
    if APR.NavigationAdapter and APR.NavigationAdapter.RefreshActivity then
        APR.NavigationAdapter:RefreshActivity(active)
    end
